/** Liang hyphenation unit tests. Pattern-word expectations were generated by running the same vendored patterns through Hypher (the reference implementation of this pattern format); exception-word expectations come from hyphen.tex's own exception list, which Hypher's data omits — TeX refuses pro-ject and as-so-ci-ate, and so do we. */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { hyphenationOffsets, languageFor, resolveLimits as resolveLimitsTyped } from '../src/hyphenate.ts';
import { byShape } from './fakes.ts';

const resolveLimits = byShape(resolveLimitsTyped);

const en = languageFor('en-US');

const partsToOffsets = (parts: any) => {
  const out: any[] = [];
  let pos = 0;
  for (const p of parts.slice(0, -1)) out.push((pos += p.length));
  return out;
};

test('language resolution: exact tag, primary subtag, unknown', () => {
  assert.ok(languageFor('en-us'));
  assert.ok(languageFor('en'));
  assert.equal(languageFor('en-GB'), languageFor('en')); // primary-subtag fallback
  assert.equal(languageFor('xx'), null);
  assert.equal(languageFor(''), null);
  assert.equal(languageFor(null), null);
});

test('pattern words match the reference implementation', () => {
  const expected = {
    hyphenation: ['hy', 'phen', 'ation'],
    computer: ['com', 'puter'],
    algorithm: ['al', 'go', 'rithm'],
    paragraph: ['para', 'graph'],
    typography: ['ty', 'pog', 'ra', 'phy'],
    university: ['uni', 'ver', 'sity'],
    beautiful: ['beau', 'ti', 'ful'],
    documentation: ['doc', 'u', 'men', 'ta', 'tion'],
    representation: ['rep', 're', 'sen', 'ta', 'tion'],
    extraordinary: ['ex', 'tra', 'or', 'di', 'nary'],
    philanthropic: ['phil', 'an', 'thropic']
  };
  for (const [word, parts] of Object.entries(expected)) {
    assert.deepEqual(hyphenationOffsets(word, en), partsToOffsets(parts), word);
  }
});

test('hyphen.tex exceptions override the patterns', () => {
  assert.deepEqual(hyphenationOffsets('associate', en), [2, 4]); // as-so-ciate, not as-so-ci-ate
  assert.deepEqual(hyphenationOffsets('project', en), []); // never pro-ject
  assert.deepEqual(hyphenationOffsets('table', en), [2]); // ta-ble, granted by exception
  assert.deepEqual(hyphenationOffsets('declination', en), [3, 5, 7]);
  assert.deepEqual(hyphenationOffsets('Table', en), [2]); // case-insensitive lookup
});

test('leftmin/rightmin guard word edges', () => {
  for (const off of hyphenationOffsets('representation', en)) {
    assert.ok(off >= en!.leftmin);
    assert.ok('representation'.length - off >= en!.rightmin);
  }
});

test('short, non-alphabetic, and sentinel words yield no candidates', () => {
  assert.deepEqual(hyphenationOffsets('a', en), []);
  assert.deepEqual(hyphenationOffsets('the', en), []);
  assert.deepEqual(hyphenationOffsets('xxxx', en), []); // under leftmin + rightmin
  assert.deepEqual(hyphenationOffsets('p0w000', en), []); // sentinels are never hyphenated
  assert.deepEqual(hyphenationOffsets('foo-bar', en), []);
  assert.deepEqual(hyphenationOffsets('12345678', en), []);
});

test('no language, no candidates', () => {
  assert.deepEqual(hyphenationOffsets('hyphenation', null), []);
});

test('hyphenate-limit-chars: an auto resolves to what the pattern set already said', () => {
  // css-text-4 §6.3.4's `auto` is "a value that adapts to the current layout", and the layout this engine has is the pattern set's own. So a document declaring nothing gets the numbers it got before, term for term — which is why reading the property costs no standing figure.
  assert.deepEqual(resolveLimits(en, {}), { before: en!.leftmin, after: en!.rightmin, total: en!.leftmin + en!.rightmin });
  assert.deepEqual(resolveLimits(en, { total: null, before: null, after: null }), { before: en!.leftmin, after: en!.rightmin, total: en!.leftmin + en!.rightmin });
  assert.deepEqual(hyphenationOffsets('representation', en, {}), hyphenationOffsets('representation', en));
});

test('hyphenate-limit-chars: each of the three binds on its own', () => {
  const all = hyphenationOffsets('representation', en);
  assert.ok(all.length > 2, 'the word divides in several places to begin with');

  const before = hyphenationOffsets('representation', en, { before: 8 });
  assert.ok(before.every((o) => o >= 8), 'nothing before the eighth character');
  assert.ok(before.length < all.length, 'and the limit actually removed something');

  const after = hyphenationOffsets('representation', en, { after: 8 });
  assert.ok(after.every((o) => 'representation'.length - o >= 8), 'nothing within eight of the end');

  assert.deepEqual(hyphenationOffsets('representation', en, { total: 20 }), [], 'a word shorter than the total is not hyphenated at all');
});

test('hyphenate-limit-chars: the limits bind an exception as well as a pattern', () => {
  // §6.3.4's sentence is about the WORD — "if the word does not meet the required minimum … then the word must not be hyphenated" — and says nothing about where the opportunity came from. `associate` is in hyphen.tex's own exception list.
  assert.ok(hyphenationOffsets('associate', en).length > 1, 'the exception divides it in several places');
  assert.deepEqual(hyphenationOffsets('associate', en, { total: 20 }), []);
  assert.ok(hyphenationOffsets('associate', en, { before: 6 }).every((o) => o >= 6));
});

const it = languageFor('it');

test('Italian: the syllables UNI 6461 asks for, two letters allowed at the end', () => {
  assert.equal(languageFor('it-IT'), it);
  const expected = {
    articolo: ['ar', 'ti', 'co', 'lo'],
    presente: ['pre', 'sen', 'te'],
    parlamento: ['par', 'la', 'men', 'to'],
    consiglio: ['con', 'si', 'glio'],
    deliberando: ['de', 'li', 'be', 'ran', 'do'],
    psicologia: ['psi', 'co', 'lo', 'gia']
  };
  for (const [word, parts] of Object.entries(expected)) assert.deepEqual(hyphenationOffsets(word, it), partsToOffsets(parts), word);
});

test('Italian: accents, elisions and punctuation', () => {
  assert.deepEqual(hyphenationOffsets('città', it), [3]); // cit-tà
  assert.deepEqual(hyphenationOffsets('finalità,', it), hyphenationOffsets('finalità', it)); // what follows a word moves nothing
  assert.deepEqual(hyphenationOffsets('“Misure', it), hyphenationOffsets('Misure', it).map((o) => o + 1)); // what precedes it moves every offset
  assert.deepEqual(hyphenationOffsets('dell’Unione', it), hyphenationOffsets("dell'Unione", it)); // both apostrophes are one letter
  const elided = 'l’articolo';
  for (const off of hyphenationOffsets(elided, it)) assert.ok(elided[off] !== '’' && elided[off - 1] !== '’', `no break beside the apostrophe at ${off}`);
  assert.deepEqual(hyphenationOffsets('5.12.2024', it), []);
  assert.deepEqual(hyphenationOffsets('D.Lgs.', it), []);
});

test('English still reads only plain letters', () => {
  assert.deepEqual(hyphenationOffsets('computer,', en), []);
  assert.deepEqual(hyphenationOffsets("computer's", en), []);
});
